/* ============================================================
   RSMaps 2.0 - Paso 52 (GENERADO)
   MIGRACION MASIVA DE METADATA LEGACY -> MODERNA
   Alcance: 72 inmuebles PUBLICADOS/PUBLICOS de IdCuenta=1, 808 fotos.

   Precondicion fisica:
   - tools/Prepare-RSMapsActiveLegacyPhotoMigration.ps1 termino OK.
   - Los 808 archivos existen en App_Data/RSMapsImages/<id>.

   Seguridad:
   - No mueve ni elimina archivos.
   - No cambia precio, estado, visibilidad ni datos comerciales.
   - Rechaza metadata moderna parcial o distinta.
   - Es idempotente: una segunda ejecucion valida el resultado y no duplica.
   - El inmueble historico 152 NO forma parte de este paso.
   ============================================================ */

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF DB_NAME() <> 'mapsMarkers'
    THROW 55200, 'Este script debe ejecutarse en la base mapsMarkers.', 1;
IF OBJECT_ID(N'dbo.RSMAPS_Inmueble', N'U') IS NULL THROW 55201, 'No existe dbo.RSMAPS_Inmueble.', 1;
IF OBJECT_ID(N'dbo.RSMAPS_InmuebleImagen', N'U') IS NULL THROW 55202, 'No existe dbo.RSMAPS_InmuebleImagen.', 1;
IF OBJECT_ID(N'dbo.RSMAPS_InmuebleImagenes', N'U') IS NULL THROW 55203, 'No existe dbo.RSMAPS_InmuebleImagenes.', 1;

