(
    IdInmueble int NOT NULL,
    Orden int NOT NULL,
    NombreOriginal nvarchar(255) NOT NULL,
    ClaveAlmacenamiento nvarchar(500) NOT NULL,
    Bytes bigint NOT NULL,
    EsPortada bit NOT NULL,
    PRIMARY KEY (IdInmueble, Orden)
);

