IF (SELECT COUNT(*) FROM @Esperado) <> 808 THROW 55204, 'El manifiesto SQL no contiene exactamente 808 fotos.', 1;
IF (SELECT COUNT(DISTINCT IdInmueble) FROM @Esperado) <> 72 THROW 55205, 'El manifiesto SQL no contiene exactamente 72 inmuebles.', 1;
IF EXISTS (SELECT 1 FROM @Esperado GROUP BY IdInmueble HAVING MAX(Orden) > 40 OR SUM(CASE WHEN EsPortada=1 THEN 1 ELSE 0 END) <> 1) THROW 55206, 'Orden o portada invalidos en manifiesto.', 1;
IF EXISTS (SELECT 1 FROM @Esperado WHERE IdInmueble=152) THROW 55207, 'Seguridad: el inmueble historico 152 no debe migrarse en este paso.', 1;

;WITH Objetivo AS
(
    SELECT IdInmueble, COUNT(*) AS Esperadas FROM @Esperado GROUP BY IdInmueble
)
SELECT 1 AS Dummy INTO #Precondicion FROM Objetivo WHERE 1=0;

IF EXISTS (SELECT 1 FROM (SELECT DISTINCT IdInmueble FROM @Esperado) e LEFT JOIN dbo.RSMAPS_Inmueble i ON i.idInmueble=e.IdInmueble WHERE i.idInmueble IS NULL OR i.IdCuenta<>1 OR i.EstadoCodigo<>'PUBLICADO' OR i.VisibilidadCodigo<>'PUBLICO')
    THROW 55208, 'Precondicion fallida: algun inmueble ya no es PUBLICADO/PUBLICO de la cuenta 1.', 1;

IF EXISTS (SELECT 1 FROM (SELECT IdInmueble, COUNT(*) Esperadas FROM @Esperado GROUP BY IdInmueble) e OUTER APPLY (SELECT ISNULL(MAX(ii.Imagenes),0) Legacy FROM dbo.RSMAPS_InmuebleImagenes ii WHERE ii.idInmueble=e.IdInmueble) x WHERE x.Legacy<>e.Esperadas)
    THROW 55209, 'Precondicion fallida: algun contador legacy ya no coincide con el manifiesto.', 1;

DECLARE @MetadataActual int = (SELECT COUNT(*) FROM dbo.RSMAPS_InmuebleImagen f WHERE EXISTS (SELECT 1 FROM @Esperado e WHERE e.IdInmueble=f.IdInmueble));

IF @MetadataActual > 0
BEGIN
    IF @MetadataActual <> 808 THROW 55210, 'Existe metadata moderna parcial o adicional en los inmuebles objetivo. No se modifica nada.', 1;
    IF EXISTS
    (
        SELECT 1 FROM @Esperado e
        LEFT JOIN dbo.RSMAPS_InmuebleImagen f
          ON f.IdInmueble=e.IdInmueble AND f.Orden=e.Orden AND f.NombreOriginal=e.NombreOriginal AND f.ClaveAlmacenamiento=e.ClaveAlmacenamiento AND f.MimeType='image/jpeg' AND f.Bytes=e.Bytes AND f.EsPortada=e.EsPortada AND f.Activo=1
        WHERE f.IdImagen IS NULL
    )
        THROW 55211, 'La metadata moderna existente no coincide exactamente con el manifiesto. No se modifica nada.', 1;
    SELECT 72 AS InmueblesMigrados, 808 AS FotosModernasActivas, 'OK - PASO 52 YA ESTABA MIGRADO' AS EstadoPaso52;
    RETURN;
END;

BEGIN TRY
    BEGIN TRANSACTION;

    INSERT dbo.RSMAPS_InmuebleImagen (IdInmueble,IdCuenta,ClaveAlmacenamiento,NombreOriginal,MimeType,Bytes,Orden,EsPortada,Activo,FechaAltaUtc)
    SELECT e.IdInmueble,1,e.ClaveAlmacenamiento,e.NombreOriginal,'image/jpeg',e.Bytes,e.Orden,e.EsPortada,1,SYSUTCDATETIME() FROM @Esperado e ORDER BY e.IdInmueble,e.Orden;

    UPDATE ii SET ii.Imagenes=e.Esperadas
    FROM dbo.RSMAPS_InmuebleImagenes ii
    JOIN (SELECT IdInmueble,COUNT(*) Esperadas FROM @Esperado GROUP BY IdInmueble) e ON e.IdInmueble=ii.idInmueble;

    INSERT dbo.RSMAPS_InmuebleImagenes (idInmueble,Imagenes)
    SELECT e.IdInmueble,e.Esperadas FROM (SELECT IdInmueble,COUNT(*) Esperadas FROM @Esperado GROUP BY IdInmueble) e
    WHERE NOT EXISTS (SELECT 1 FROM dbo.RSMAPS_InmuebleImagenes ii WHERE ii.idInmueble=e.IdInmueble);

    IF (SELECT COUNT(*) FROM dbo.RSMAPS_InmuebleImagen f WHERE f.Activo=1 AND EXISTS (SELECT 1 FROM @Esperado e WHERE e.IdInmueble=f.IdInmueble)) <> 808 THROW 55212, 'Verificacion fallida: no quedaron 808 fotos modernas activas.', 1;
    IF EXISTS (SELECT 1 FROM dbo.RSMAPS_InmuebleImagen f WHERE f.Activo=1 AND EXISTS (SELECT 1 FROM @Esperado e WHERE e.IdInmueble=f.IdInmueble) GROUP BY f.IdInmueble HAVING SUM(CASE WHEN f.EsPortada=1 THEN 1 ELSE 0 END)<>1) THROW 55213, 'Verificacion fallida: alguna propiedad no tiene exactamente una portada.', 1;
    IF EXISTS
    (
        SELECT 1 FROM @Esperado e
        LEFT JOIN dbo.RSMAPS_InmuebleImagen f
          ON f.IdInmueble=e.IdInmueble AND f.Orden=e.Orden AND f.NombreOriginal=e.NombreOriginal AND f.ClaveAlmacenamiento=e.ClaveAlmacenamiento AND f.MimeType='image/jpeg' AND f.Bytes=e.Bytes AND f.EsPortada=e.EsPortada AND f.Activo=1
        WHERE f.IdImagen IS NULL
    )
        THROW 55214, 'Verificacion fallida: la metadata insertada no coincide con el manifiesto.', 1;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

SELECT
    COUNT(DISTINCT f.IdInmueble) AS InmueblesMigrados,
    COUNT(*) AS FotosModernasActivas,
    SUM(CASE WHEN f.EsPortada=1 THEN 1 ELSE 0 END) AS PortadasModernas,
    'OK - 72 INMUEBLES / 808 FOTOS MIGRADOS A METADATA MODERNA' AS EstadoPaso52
FROM dbo.RSMAPS_InmuebleImagen f
WHERE f.Activo=1 AND EXISTS (SELECT 1 FROM @Esperado e WHERE e.IdInmueble=f.IdInmueble);
